const data = $input.all();
const totalRevenue = data.reduce((sum, d) => sum + parseFloat(d.json.revenue), 0);
const totalExpenses = data.reduce((sum, d) => sum + parseFloat(d.json.expenses), 0);
const netProfit = totalRevenue - totalExpenses;
const profitMargin = (netProfit / totalRevenue * 100).toFixed(2);
return {json: {period: '30 days', total_revenue: totalRevenue, total_expenses: totalExpenses, net_profit: netProfit, profit_margin: profitMargin, daily_data: data.map(d => d.json)}};
